changeSet.sql:
CREATE TABLE finances.strategies ( id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, external_id UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE, user_id BIGINT NOT NULL REFERENCES system.users(id) ON DELETE CASCADE, name TEXT NOT NULL, is_default BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT strategies_user_name_key UNIQUE (user_id, name) );
CREATE UNIQUE INDEX strategies_one_default_per_user ON finances.strategies (user_id) WHERE is_default;
CREATE TABLE finances.strategy_classes ( id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, external_id UUID NOT NULL DEFAULT gen_random_uuid() UNIQUE, strategy_id BIGINT NOT NULL REFERENCES finances.strategies(id) ON DELETE CASCADE, name TEXT NOT NULL, target_percentage NUMERIC(5, 2), position INT NOT NULL, is_default BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT strategy_classes_strategy_name_key UNIQUE (strategy_id, name), CONSTRAINT strategy_classes_target_range CHECK (target_percentage IS NULL OR (target_percentage >= 0 AND target_percentage <= 100)), CONSTRAINT strategy_classes_default_has_no_target CHECK (NOT is_default OR target_percentage IS NULL) );
CREATE INDEX strategy_classes_strategy_id_idx ON finances.strategy_classes (strategy_id);

INSERT INTO finances.strategies (user_id, name, is_default)
SELECT users.id, 'Sem estratégia', true FROM system.users;

INSERT INTO finances.strategy_classes (strategy_id, name, position, is_default)
SELECT strategies.id, 'Não definida', 0, true
FROM finances.strategies
WHERE strategies.is_default;

ALTER TABLE finances.stock_holdings
    ADD COLUMN strategy_class_id BIGINT REFERENCES finances.strategy_classes(id) ON DELETE RESTRICT,
    ADD COLUMN class_target_percentage NUMERIC(5, 2)
        CONSTRAINT stock_holdings_class_target_range
        CHECK (class_target_percentage IS NULL OR (class_target_percentage >= 0 AND class_target_percentage <= 100));
ALTER TABLE finances.crypto_holdings
    ADD COLUMN strategy_class_id BIGINT REFERENCES finances.strategy_classes(id) ON DELETE RESTRICT,
    ADD COLUMN class_target_percentage NUMERIC(5, 2)
        CONSTRAINT crypto_holdings_class_target_range
        CHECK (class_target_percentage IS NULL OR (class_target_percentage >= 0 AND class_target_percentage <= 100));
ALTER TABLE finances.fund_holdings
    ADD COLUMN strategy_class_id BIGINT REFERENCES finances.strategy_classes(id) ON DELETE RESTRICT,
    ADD COLUMN class_target_percentage NUMERIC(5, 2)
        CONSTRAINT fund_holdings_class_target_range
        CHECK (class_target_percentage IS NULL OR (class_target_percentage >= 0 AND class_target_percentage <= 100));

UPDATE finances.stock_holdings
SET strategy_class_id = strategy_classes.id
FROM finances.wallets
JOIN finances.strategies ON strategies.user_id = wallets.user_id AND strategies.is_default
JOIN finances.strategy_classes ON strategy_classes.strategy_id = strategies.id
WHERE wallets.id = stock_holdings.wallet_id;

UPDATE finances.crypto_holdings
SET strategy_class_id = strategy_classes.id
FROM finances.wallets
JOIN finances.strategies ON strategies.user_id = wallets.user_id AND strategies.is_default
JOIN finances.strategy_classes ON strategy_classes.strategy_id = strategies.id
WHERE wallets.id = crypto_holdings.wallet_id;

UPDATE finances.fund_holdings
SET strategy_class_id = strategy_classes.id
FROM finances.wallets
JOIN finances.strategies ON strategies.user_id = wallets.user_id AND strategies.is_default
JOIN finances.strategy_classes ON strategy_classes.strategy_id = strategies.id
WHERE wallets.id = fund_holdings.wallet_id;

ALTER TABLE finances.stock_holdings ALTER COLUMN strategy_class_id SET NOT NULL;
ALTER TABLE finances.crypto_holdings ALTER COLUMN strategy_class_id SET NOT NULL;
ALTER TABLE finances.fund_holdings ALTER COLUMN strategy_class_id SET NOT NULL;

CREATE INDEX stock_holdings_strategy_class_id_idx ON finances.stock_holdings (strategy_class_id);
CREATE INDEX crypto_holdings_strategy_class_id_idx ON finances.crypto_holdings (strategy_class_id);
CREATE INDEX fund_holdings_strategy_class_id_idx ON finances.fund_holdings (strategy_class_id);

rollback.sql:
ALTER TABLE finances.stock_holdings DROP COLUMN strategy_class_id, DROP COLUMN class_target_percentage;
ALTER TABLE finances.crypto_holdings DROP COLUMN strategy_class_id, DROP COLUMN class_target_percentage;
ALTER TABLE finances.fund_holdings DROP COLUMN strategy_class_id, DROP COLUMN class_target_percentage;
