changeSet.sql:
CREATE FUNCTION finances.create_default_strategy() RETURNS trigger AS $$
DECLARE
    default_strategy_id BIGINT;
BEGIN
    INSERT INTO finances.strategies (user_id, name, is_default)
    VALUES (NEW.id, 'Sem estratégia', true)
    RETURNING id INTO default_strategy_id;

    INSERT INTO finances.strategy_classes (strategy_id, name, position, is_default)
    VALUES (default_strategy_id, 'Não definida', 0, true);

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER users_create_default_strategy
    AFTER INSERT ON system.users
    FOR EACH ROW EXECUTE FUNCTION finances.create_default_strategy();

CREATE FUNCTION finances.default_strategy_class() RETURNS trigger AS $$
BEGIN
    IF NEW.strategy_class_id IS NULL THEN
        SELECT strategy_classes.id INTO NEW.strategy_class_id
        FROM finances.wallets
        JOIN finances.strategies ON strategies.user_id = wallets.user_id AND strategies.is_default
        JOIN finances.strategy_classes ON strategy_classes.strategy_id = strategies.id
        WHERE wallets.id = NEW.wallet_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER stock_holdings_default_strategy_class
    BEFORE INSERT ON finances.stock_holdings
    FOR EACH ROW EXECUTE FUNCTION finances.default_strategy_class();
CREATE TRIGGER crypto_holdings_default_strategy_class
    BEFORE INSERT ON finances.crypto_holdings
    FOR EACH ROW EXECUTE FUNCTION finances.default_strategy_class();
CREATE TRIGGER fund_holdings_default_strategy_class
    BEFORE INSERT ON finances.fund_holdings
    FOR EACH ROW EXECUTE FUNCTION finances.default_strategy_class();

rollback.sql:
DROP TRIGGER stock_holdings_default_strategy_class ON finances.stock_holdings;
DROP TRIGGER crypto_holdings_default_strategy_class ON finances.crypto_holdings;
DROP TRIGGER fund_holdings_default_strategy_class ON finances.fund_holdings;
DROP FUNCTION finances.default_strategy_class();
DROP TRIGGER users_create_default_strategy ON system.users;
DROP FUNCTION finances.create_default_strategy();
